home_dir=settings.BASE_DIR
qr_dir=os.path.join(home_dir, "main/static/qr")
photo=os.path.join(home_dir, "main/static/photo")
def MkQr(x):
	data=x
	qr=qrcode.QRCode(version=2, error_correction=qrcode.constants.ERROR_CORRECT_L, box_size=10, border=1)
	qr.add_data(data)
	qr.make(fit=True)
	img=qr.make_image(fill_color="black", back_color="white")
	file="%s.png" %(x)
	img.save(os.path.join(qr_dir, file))
#	img.save("/static/qr/%s.png" %(x))

def Kids_ID():
	if Register.objects.exists():
		if datetime.now().strftime("1%y%m%d") in Register.objects.latest('id').k_id:
			m=datetime.now().strftime("1%y%m%d")+f"{(int(Register.objects.latest('id').k_id[7:len(Register.objects.latest('id').k_id)])+1):02d}"
		else:
			m=datetime.now().strftime("1%y%m%d01")
	else:
		m=datetime.now().strftime("1%y%m%d01")
	return m

def ImgResize(x):
	img=Image.open(x)
	w,h=img.size
	if w > 290 and h > 290:
		resize_img=img.resize((290,290))
		resize_img.save(x)
	return x

